<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Verifikasi Surat</title><style>body{font-family:Arial,sans-serif;background:#f3f6fa;margin:0;padding:32px}.box{max-width:620px;margin:auto;background:#fff;border-radius:14px;padding:28px;box-shadow:0 8px 30px #0001}.ok{color:#087f5b;font-weight:700}.row{padding:12px 0;border-bottom:1px solid #eee}.muted{color:#667085}</style></head><body><div class="box"><h2>Verifikasi Surat Desa</h2><p class="ok">✓ Dokumen terdaftar dan berstatus APPROVED.</p><div class="row"><span class="muted">Jenis Surat</span><br><strong>{{ $letter->letterType->name }}</strong></div><div class="row"><span class="muted">Nomor Surat</span><br><strong>{{ $letter->letter_number }}</strong></div><div class="row"><span class="muted">Tanggal Terbit</span><br>{{ optional($letter->issued_at)->format('d-m-Y') }}</div><p class="muted">Halaman ini hanya menampilkan informasi verifikasi minimum.</p></div></body></html>